def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
      - Multiplos de 3 son 'Fizz'
      - Multiplos de 5 son 'Buzz'
      - Multiplos de 3 y 5 son 'FizzBuzz'
      - Los demás números como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == max_elemento:
            racha_actual += 1
        else:
            racha_actual = 1
            max_elemento = lista[i]

    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minúscula y las siguientes con la inicial en mayúscula,
    sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(word) == 1:
                result.append(word)
            else:
                result.append(word[0].upper() + word[1:])
    return " ".join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def formatear_bytes(n: int) -> str:
    """
    Convierte una cantidad de bytes a texto legible usando base 1024
    y las unidades B, KB, MB, GB.

    Los bytes se muestran sin decimales y las demas unidades con UN decimal.

    Args:
        n: Cantidad de bytes a convertir (número entero positivo).

    Returns:
        String con la representación en texto de bytes.
    """
    if n <= 0:
        return "0 B"

    if n <= 1023:
        return f"{n} B"
    elif n <= 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n <= 1024 * 1024 * 1024:
        return f"{n / (1024 ** 2):.1f} MB"
    else:
        return f"{n / (1024 ** 3):.1f} GB"

def anidar(plano: dict) -> dict:
    """
    Recorre un diccionario plano y crea un diccionario anidado
    donde cada clave que contenga puntos se convierte en un diccionario
    de profundidad máxima igual al número de puntos.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 2} -> {'a': {'b': {'c': 2}}}
        {'a.b.c.d': 3} -> {'a': {'b': {'c': {'d': 3}}}}
    """
    resultado = {}
    for clave, valor in plano.items():
        if '.' in clave:
            partes = clave.split('.')
            nivel = len(partes) - 1
            if nivel > 0:
                if nivel == 1:
                    resultado[clave] = valor
                else:
                    resultado[clave] = {'c': valor}
                    resultado[clave][clave.split('.')[-2]] = valor
        else:
            resultado[clave] = valor
    return resultado

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024.

    Unidades: B, KB, MB, GB.
    B va sin decimales, KB, MB, GB con decimales.

    Args:
        n: Número de bytes a convertir.

    Returns:
        String representando el tamaño en formato legible.
    """
    if n <= 0:
        return "0 B"

    if n <= 1024:
        return f"{n} B"
    elif n <= 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n <= 1024 * 1024 * 1024:
        return f"{n / 1024 / 1024:.1f} MB"
    else:
        return f"{n / 1024 / 1024 / 1024:.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

def titular(s: str) -> str:
    """
    Capitaliza la primera letra de cada palabra, excepto por 'de', 'del', 'la', 'las', 'el', 'los' e 'y'
    cuando no son la primera palabra.

    Args:
        s: La cadena de texto a procesar.

    Returns:
        La cadena con las palabras capitalizadas.
    """
    result = []
    for i, char in enumerate(s):
        if char == ' ':
            result.append(char)
        elif i == 0:
            if char in ('de', 'del', 'la', 'las', 'el', 'los', 'y'):
                result.append(char)
            else:
                result.append(char.upper())
        else:
            result.append(char)
    return ''.join(result)


