def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en formato romano.

    Args:
        a: Primer número en formato romano.
        b: Segundo número en formato romano.

    Returns:
        El resultado de la suma en formato romano.

    Raises:
        ValueError: Si los números no son válidos en formato romano.
    """
    def valor_romano(num: str) -> int:
        """Convierte un número romano a entero."""
        if num == "":
            raise ValueError("Número romano vacío")
        if len(num) > 4:
            raise ValueError("Número romano demasiado largo")
        if num[0] == "I":
            return -1 + int(num[1:])
        elif num[0] == "V":
            return 5 + int(num[1:])
        elif num[0] == "X":
            return 10 + int(num[1:])
        elif num[0] == "L":
            return 50 + int(num[1:])
        elif num[0] == "C":
            return 100 + int(num[1:])
        elif num[0] == "D":
            return 500 + int(num[1:])
        elif num[0] == "M":
            return 1000 + int(num[1:])
        else:
            raise ValueError(f"Error en el número romano: {num}")

    try:
        a_val = valor_romano(a)
        b_val = valor_romano(b)
    except ValueError as e:
        raise ValueError(f"Error en la entrada: {e}")

    if a_val > b_val:
        return valor_romano(str(a_val - b_val))
    else:
        return valor_romano(str(b_val - a_val))

def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepción, la reintenta hasta 'veces' intentos en total.
    Si todos los intentos fallan, vuelve a lanzar la última excepción.

    Args:
        fn: Función que puede lanzar excepciones.
        veces: Número máximo de intentos permitidos.

    Returns:
        El resultado de la primera función que no lanza excepción.
    """
    for _ in range(veces):
        try:
            return fn()
        except Exception:
            continue
    return None
